-- 태도사 사전검토 표준 문장 V1 (현장조건 검토 · 종합 의견)
-- Cloudflare D1 Console에서 아래 문장을 한 줄씩 순서대로 실행하세요.
-- category: site(현장조건) / opinion(종합 의견)
-- group_key: site = shade(음영발생), slope(경사도 과다), road(진입로·배수로), struct(건물 구조강화)
--            opinion = possible(진행 가능), conditional(조건부 진행 가능), not_possible(진행 불가능)
-- 삭제는 is_active = 0 으로 숨김 처리합니다(기존 검토 결과 기록 보존).

CREATE TABLE IF NOT EXISTS precheck_phrases (id INTEGER PRIMARY KEY AUTOINCREMENT, category TEXT NOT NULL CHECK (category IN ('site', 'opinion')), group_key TEXT NOT NULL, text TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1, created_by INTEGER, updated_by INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_precheck_phrases_group ON precheck_phrases(category, group_key, is_active, sort_order);

